import { Switch as SwitchPrimitive, useSwitch, useSwitchContext } from '@ark-ui/solid/switch';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import styles from './Switch.module.css';

type SwitchSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type SwitchRootProps = ComponentProps<typeof SwitchPrimitive.Root> & {
  size?: SwitchSize;
};
type SwitchRootProviderProps = ComponentProps<typeof SwitchPrimitive.RootProvider> & {
  size?: SwitchSize;
};

function Switch(props: SwitchRootProps) {
  const [local, others] = splitProps(props, ['children', 'class', 'size']);

  return (
    <SwitchPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="switch-root"
    >
      {local.children}
    </SwitchPrimitive.Root>
  );
}

function SwitchRootProvider(props: SwitchRootProviderProps) {
  const [local, others] = splitProps(props, ['children', 'class', 'size']);

  return (
    <SwitchPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="switch-root-provider"
    >
      {local.children}
    </SwitchPrimitive.RootProvider>
  );
}

function SwitchControl(props: ComponentProps<typeof SwitchPrimitive.Control>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <SwitchPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="switch-control"
    >
      {resolvedChildren() ?? <SwitchThumb />}
    </SwitchPrimitive.Control>
  );
}

function SwitchThumb(props: ComponentProps<typeof SwitchPrimitive.Thumb>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SwitchPrimitive.Thumb
      class={clsx(styles.thumb, local.class)}
      {...others}
      data-slot="switch-thumb"
    />
  );
}

function SwitchLabel(props: ComponentProps<typeof SwitchPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SwitchPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="switch-label"
    />
  );
}

const SwitchContext = SwitchPrimitive.Context;
const SwitchHiddenInput = SwitchPrimitive.HiddenInput;

export {
  Switch,
  SwitchContext,
  SwitchControl,
  SwitchHiddenInput,
  SwitchLabel,
  SwitchRootProvider,
  SwitchThumb,
  useSwitch,
  useSwitchContext,
};
export type {
  SwitchCheckedChangeDetails,
  SwitchContextProps,
  SwitchControlProps,
  SwitchHiddenInputProps,
  SwitchLabelProps,
  SwitchThumbProps,
  UseSwitchContext,
  UseSwitchProps,
  UseSwitchReturn,
} from '@ark-ui/solid/switch';
export type { SwitchRootProps, SwitchRootProviderProps, SwitchSize };

@layer moduix.components {
  .root {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-switch-gap, var(--moduix-spacing-2));
    width: fit-content;
    vertical-align: middle;
    color: var(--moduix-color-foreground);
    cursor: pointer;

    &[data-disabled],
    &[data-readonly] {
      cursor: default;
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .control {
    box-sizing: border-box;
    position: relative;
    flex: none;
    width: 2.75rem;
    height: var(--moduix-size-xs);
    border: var(--moduix-border-width-sm) solid
      var(--moduix-switch-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-switch-bg, var(--moduix-color-muted));
    user-select: none;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default);

    &[data-state='checked'] {
      border-color: var(--moduix-switch-bg-checked, var(--moduix-color-primary));
      background-color: var(--moduix-switch-bg-checked, var(--moduix-color-primary));
    }

    &[data-focus-visible] {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
      outline-color: var(--moduix-color-destructive);
    }

    @media (hover: hover) {
      &[data-state='unchecked'][data-hover]:not([data-readonly], [data-disabled]) {
        background-color: var(--moduix-color-accent);
      }
    }
  }

  .root[data-size='xs'] .control {
    width: 1.75rem;
    height: 1rem;
  }

  .root[data-size='sm'] .control {
    width: 2.25rem;
    height: 1.25rem;
  }

  .root[data-size='lg'] .control {
    width: 3.25rem;
    height: 1.75rem;
  }

  .root[data-size='xl'] .control {
    width: 3.75rem;
    height: var(--moduix-size-sm);
  }

  /* Sized and placed against the track, so plain width and height overrides on the control keep it aligned. */
  .thumb {
    position: absolute;
    top: 50%;
    inset-inline-start: var(--moduix-spacing-0-5);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: calc(100% - var(--moduix-spacing-0-5) * 2);
    aspect-ratio: 1;
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-switch-thumb-bg, var(--moduix-color-background));
    color: var(--moduix-color-muted);
    box-shadow: var(--moduix-shadow-sm);
    translate: 0 -50%;
    transition:
      inset-inline-start var(--moduix-transition-default),
      translate var(--moduix-transition-default),
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &[data-state='checked'] {
      inset-inline-start: calc(100% - var(--moduix-spacing-0-5));
      background-color: var(--moduix-switch-thumb-bg, var(--moduix-color-primary-foreground));
      color: var(--moduix-color-primary);
      translate: -100% -50%;

      &[dir='rtl'] {
        translate: 100% -50%;
      }
    }

    & > svg {
      width: 65%;
      height: 65%;
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
  }
}
